-- Journeys build plan J13 — invoices: drafts, numbers, due dates, plan
-- issuing. Generated by `prisma migrate diff`, then hand-extended: the
-- sequence (PD-11), the backfill, and the CHECK that makes "issued" mean
-- numbered and dated.

-- AlterTable
ALTER TABLE "BillingEntry" ADD COLUMN     "dueAt" DATE,
ADD COLUMN     "invoiceNumber" TEXT,
ADD COLUMN     "paymentTermDays" INTEGER,
ADD COLUMN     "plannedInvoiceId" TEXT,
ALTER COLUMN "issuedAt" DROP NOT NULL,
ALTER COLUMN "issuedAt" DROP DEFAULT;

-- Invoice numbers come from a sequence, not a counter row and not MAX()+1:
-- three paths issue (an admin issuing a draft, a planned invoice, lazy
-- subscription generation) and they can run at once. A sequence never races;
-- the price is that a rolled-back transaction burns a number, so numbers may
-- have gaps (PD-11). Hand-written — Prisma has no model for a sequence.
CREATE SEQUENCE "invoice_number_seq";

-- BACKFILL:BEGIN
-- Hand-written. `j13.test.ts` extracts everything between the BEGIN and END
-- markers and runs it over fixture rows inside a rolled-back transaction; keep
-- every statement of the backfill inside them.
--
-- Every entry that exists before this migration was an issued invoice the
-- moment it was created (there was no draft state), so each is numbered in
-- `issuedAt` order (`id` breaking a tie) with the same `INV-` + six digits that
-- `formatInvoiceNumber` (lib/invoice.ts) renders, and is due the day it was
-- issued with a term of zero — there was no term, and inventing one would put
-- an overdue mark on money nobody was ever told a date for. (Production holds
-- no data: P0-1. The fixture and the seeded dev database do.)
UPDATE "BillingEntry" AS b
SET "invoiceNumber" = 'INV-' || lpad(n."rn"::text, 6, '0'),
    "dueAt" = b."issuedAt"::date,
    "paymentTermDays" = 0
FROM (
  SELECT "id", row_number() OVER (ORDER BY "issuedAt" ASC, "id" ASC) AS "rn"
  FROM "BillingEntry"
  WHERE "issuedAt" IS NOT NULL
) AS n
WHERE b."id" = n."id";

-- The next issued invoice continues after the backfilled ones. `setval`'s third
-- argument is "is_called": with nothing backfilled the first number is 1.
SELECT setval('invoice_number_seq', GREATEST((SELECT count(*) FROM "BillingEntry"), 1), (SELECT count(*) FROM "BillingEntry") > 0);
-- BACKFILL:END

-- A row that says it was issued must carry the number and the day it is due —
-- whatever wrote it. The three writers are all in this codebase, and the CHECK
-- is for the fourth: a script, a console, a future edit that forgets one half.
-- `issuedAt IS NULL OR (...)`, so a draft is free of both. Proven by a direct
-- insert in `j13.test.ts`.
ALTER TABLE "BillingEntry"
  ADD CONSTRAINT "BillingEntry_issued_is_complete"
  CHECK ("issuedAt" IS NULL OR ("invoiceNumber" IS NOT NULL AND "dueAt" IS NOT NULL));

-- CreateIndex
CREATE UNIQUE INDEX "BillingEntry_invoiceNumber_key" ON "BillingEntry"("invoiceNumber");

-- CreateIndex
CREATE UNIQUE INDEX "BillingEntry_plannedInvoiceId_key" ON "BillingEntry"("plannedInvoiceId");

-- AddForeignKey
ALTER TABLE "BillingEntry" ADD CONSTRAINT "BillingEntry_plannedInvoiceId_fkey" FOREIGN KEY ("plannedInvoiceId") REFERENCES "PlannedInvoice"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
